<script setup lang="ts">
import { ArrowLeft, ArrowUpRight, Check, LoaderCircle, Play, ShieldCheck } from 'lucide-vue-next'
definePageMeta({ layout: 'app' })
const route = useRoute(); const api = useApi()
const { data: job, refresh } = await useAsyncData(`job-${route.params.id}`, () => api.request<any>(`/portal/jobs/${route.params.id}`).catch(() => null))
if (!job.value) throw createError({ statusCode: 404, statusMessage: 'Job not found' })
const analyzing = ref(false); const chosen = ref('')
async function analyze() { analyzing.value = true; try { await api.request(`/portal/jobs/${job.value._id}/analyze`, { method: 'POST' }); await refresh() } finally { analyzing.value = false } }
async function award(bid: any) { chosen.value = bid._id; try { await api.request(`/portal/jobs/${job.value._id}/award`, { method: 'POST', body: { bidId: bid._id, contractorOrgId: '' } }); await refresh() } finally { chosen.value = '' } }
async function release(i: number) { await api.request(`/portal/escrow/${job.value._id}/release`, { method: 'POST', body: { index: i } }); await refresh() }
</script>
<template>
  <div v-if="job"><div class="mb-5 flex items-center justify-between"><NuxtLink to="/app/home" class="inline-flex items-center gap-2 font-mono text-[9px] uppercase tracking-[.08em] text-ink/40"><ArrowLeft :size="12" /> Home jobs</NuxtLink><StatusPill :status="job.status" /></div>
    <div class="grid gap-5 xl:grid-cols-12"><div class="xl:col-span-8"><div class="rounded-2xl border border-ink/12 bg-bone p-5 md:p-7"><p class="label-mono text-signal-deep">{{ job.ref }} · {{ job.propertyType }}</p><h1 class="type-product-hero mt-2">{{ job.address }}</h1><p class="mt-2 text-[13px] text-ink/55">{{ job.city }} · {{ job.issue }}</p>
      <div class="mt-6 grid gap-4 sm:grid-cols-[1fr_auto]"><div class="flex min-h-48 items-center justify-center rounded-xl bg-ink text-bone"><div class="text-center"><Play :size="28" class="mx-auto text-mint" /><p class="mt-2 text-[12px]">Camera walkthrough · {{ job.videoUrl || 'demo footage' }}</p><p class="mt-1 font-mono text-[8px] uppercase tracking-[.08em] text-bone/35">Secure review · demo</p></div></div><div v-if="job.healthScore" class="flex flex-col justify-center rounded-xl border border-ink/12 p-5 text-center sm:w-36"><p class="font-display text-[46px] leading-none">{{ job.healthScore }}</p><p class="mt-1 font-mono text-[8px] uppercase tracking-[.08em] text-ink/35">Line health</p></div><div v-else class="flex flex-col justify-center rounded-xl border border-dashed border-ink/20 p-5 text-center sm:w-44"><p class="text-[12px] text-ink/45">Footage uploaded. Run the visual analysis.</p><button class="btn btn-dark mt-3 !min-h-8 !text-[9px]" :disabled="analyzing" @click="analyze"><LoaderCircle v-if="analyzing" :size="12" class="animate-spin" /> {{ analyzing ? 'Analyzing…' : 'Analyze footage' }}</button></div></div>
      <div v-if="job.defects?.length" class="mt-5"><p class="font-mono text-[8px] uppercase tracking-[.08em] text-ink/35">Findings</p><div class="mt-2 divide-y divide-ink/10 border-y border-ink/10"><div v-for="d in job.defects" :key="d.type" class="grid grid-cols-[1fr_auto_auto] items-center gap-3 py-3 text-[12px]"><span>{{ d.type }} <span class="text-ink/35">· {{ d.distanceFt }} ft</span></span><span class="font-mono text-[9px] text-ink/40">{{ Math.round((d.confidence||0)*100) }}%</span><StatusPill :status="d.severity" /></div></div></div>
      <div v-if="job.certificate" class="mt-5 rounded-xl bg-mint/15 p-4"><p class="flex items-center gap-2 font-mono text-[8px] uppercase tracking-[.08em] text-mint-deep"><ShieldCheck :size="12" /> Health certificate issued</p><p class="mt-2 text-[12px] leading-relaxed text-ink/60">{{ job.certificate.summary }}</p></div></div></div>
      <aside class="space-y-4 xl:col-span-4"><div class="rounded-xl border border-ink/12 bg-bone p-5"><div class="flex items-center justify-between"><p class="font-display text-[20px]">Contractor bids</p><span class="font-mono text-[9px] text-ink/35">{{ job.bids?.length || 0 }}</span></div><div v-if="job.bids?.length" class="mt-3 space-y-2"><div v-for="b in job.bids" :key="b._id" class="rounded-lg border p-3" :class="b.status === 'awarded' ? 'border-mint bg-mint/10' : 'border-ink/12'"><div class="flex items-center justify-between"><p class="text-[12px] font-semibold">{{ b.contractorName }}</p><StatusPill :status="b.status" /></div><p class="mt-1 font-display text-[22px]">{{ money(b.amountUsd) }}</p><p class="text-[10px] text-ink/45">{{ b.days }} days · {{ b.note }}</p><button v-if="job.status==='bidding'" class="mt-2 w-full rounded-md border border-ink/15 py-1.5 font-mono text-[8px] uppercase tracking-[.06em] hover:border-ink" :disabled="chosen===b._id" @click="award(b)">Award & fund escrow</button></div></div><p v-else class="mt-3 text-[12px] text-ink/45">No bids yet. Run the analysis to publish the scope.</p></div>
        <div v-if="job.escrow" class="rounded-xl bg-ink p-5 text-bone"><p class="font-mono text-[8px] uppercase tracking-[.08em] text-mint">Vomtek Assure escrow</p><p class="mt-2 font-display text-[28px]">{{ money(job.escrow.amount) }}</p><div class="mt-3 space-y-2"><div v-for="(m,i) in job.escrow.milestones" :key="m.label" class="flex items-center justify-between border-t border-bone/10 pt-2 text-[11px]"><div><p>{{ m.label }}</p><p class="font-mono text-[8px] text-bone/35">{{ money(m.amount) }}</p></div><div class="flex items-center gap-2"><span class="font-mono text-[8px] uppercase" :class="m.status==='released'?'text-mint':'text-bone/35'">{{ m.status }}</span><button v-if="m.status!=='released'" class="rounded-full border border-bone/20 px-2 py-1 font-mono text-[7.5px] uppercase hover:border-mint hover:text-mint" @click="release(i)">Release</button></div></div></div></div>
        <NuxtLink to="/contact" class="btn btn-outline w-full !min-h-9 !text-[10px]">Need help? Talk to Vomtek <ArrowUpRight :size="12" /></NuxtLink></aside></div>
  </div>
</template>
